contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // single public test function taking all inputs
    function run(address from, address caddress, address[] memory _tos, uint v) public payable {
        // no precondition on parameters
        // record balances before
        uint beforeC = address(c).balance;
        uint beforeSelf = address(this).balance;

        // perform the call and detect revert
        bool reverted;
        bool returned;
        try c.transfer(from, caddress, _tos, v) returns (bool r) {
            reverted = false;
            returned = r;
        } catch {
            reverted = true;
            returned = false;
        }

        uint afterC = address(c).balance;
        uint afterSelf = address(this).balance;

        // General rule: returned==true exactly when not reverted, and balances unchanged when it returned true
        assert((!reverted && returned && afterC == beforeC && afterSelf == beforeSelf) || (reverted && !returned));
    }

    receive() external payable { }
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // Single public test function driving c.transfer and asserting a general rule
    function run(address from, address caddress, address[] memory _tos, uint v) public payable {
        // require a non-empty _tos to avoid immediate revert from C.transfer's require
        require(_tos.length > 0);

        bool reverted;
        bool returnedValue;
        try c.transfer(from, caddress, _tos, v) returns (bool r) {
            reverted = false;
            returnedValue = r;
        } catch {
            reverted = true;
            returnedValue = false;
        }

        // General rule: if the call did not revert, then it must have returned true
        assert(reverted || returnedValue);
    }

    receive() external payable { }
}

